local util = require 'XLua.util'
local CoWait = CS.Engine.Lib.CoWait

------------ import ------------
local LuaPath = 'Game.Entry.ActionEntryMap'
local KTool = CS.Engine.Lib.KTool
local UIModule = CS.Engine.UI.UIModule
local UINavigationBarRoot = CS.UINavigationBarRoot
local WaitForSeconds = CS.UnityEngine.WaitForSeconds
local EasyTouch = CS.HedgehogTeam.EasyTouch.EasyTouch
local Input = CS.UnityEngine.Input
local KCookie = CS.Engine.Lib.KCookie
local ActivityConstants = import("Game.Activity.ActivityConstants")
local UIRaycastBlocker = CS.Engine.UI.UIRaycastBlocker.Instance
------------ import ------------

------------ define ------------
---@type SceneManagement
local sceneManagement = SceneManagement:GetInstance()
local Yielders = CS.Engine.Lib.Yielders
local cs_coroutine = import('XLua.cs_coroutine')
local DailyQuestDialogPath = 'Game.UI.DailyQuest.DailyQuestDialog'
------------ define ------------

---@class ActionDialog
---@field EmptyBg                        UnityEngine.RectTransform @挡点击事件的
---@field FightMap                        UnityEngine.Canvas
---@field UIFX_BattleSelectionEntryCenterToL    UnityEngine.RectTransform
---@field UIFX_BattleSelectionEntryCenterToC    UnityEngine.RectTransform
---@field UIFX_BattleSelectionEntryCenterToB    UnityEngine.RectTransform
local ActionDialog = Class("ActionDialog")

local SceneNodeName = 'ActionScenes '

function ActionDialog:__init()
    self.sceneRoot = nil
    self.isEnabled = false
    self.actionHandler = nil
    self.worldCanvas = nil
    self.actionMap = nil
    self.selectId = nil
    self.selectGo = nil
end

function ActionDialog:__delete()
    self.actionHandler = nil
    self.selectGo = nil
    self.sceneRoot = nil
    self.isEnabled = false
    self.worldCanvas = nil
    self.controller = nil
    self.selectId = nil
    self.actionMap = nil
end

function ActionDialog:OnFocus(focus)
    if focus then
        CfUtils.RefreshTopGoods({ Constants.Currency.FreeDiamondId, Constants.Currency.HpId ,Constants.GoodsId.SweepCoin})

        local navigatorBar = GetLuaBehaviour(UINavigationBarRoot.Instance.gameObject, "Game.Main.UINavigatorBar")
        if not isNull(navigatorBar) then
            if not KTool.IsNull(navigatorBar.Env) then
                navigatorBar.Env:SetCustomBackHandlerAction(function()
                    ---执行一
                    if self.isEnabled then
                        self.isEnabled = false
                        self.FightMap.enabled = false
                        if not isNull(self.sceneRoot) then
                            ---执行文本相关的定位
                            ---@type ActionEntryMap
                            local env = CfUtils.GetLuaScr(self.sceneRoot, LuaPath)
                            env:PlayCamOpenAni()
                            if not isNull(self.selectGo) then
                                CfUtils.PlayAnimator(self.selectGo.transform:Find("Anim"), "Idle")
                            end
    
                            self._showCo = cs_coroutine.start(function()
                                cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.3))
                                env:SetDailyQuestState(false)
                            end)
                        end
                    else
                        UIModule.BackDialog()
                    end
                end)
            end
        end
    end
end

function ActionDialog:Awake()
    UIRaycastBlocker:AddCondition("ActionDialogBegin")

    --self.controller.MarkPoolable = true
    Events.Broadcast(Constants.EventNames.MainHomeRoleActive, { isShow = false })

    self.actionHandler = Events.AddListener(Constants.EventNames.DAILY_QUEST_BUTTON_CLICK_ACTION, Bind(self, self.DailyQuestButtonAction))
    SetButtonAction(self.EmptyBg.gameObject, function()
        ---点击到下面的raycastTest
        if isNull(self.worldCanvas) then
            local worldCanvasGo = CS.UnityEngine.GameObject.Find("ActionCanvas")
            if not isNull(worldCanvasGo) then
                self.worldCanvas = KTool.GetComponent(worldCanvasGo, typeof(CS.UnityEngine.Canvas))
            end
        end
        if not isNull(self.worldCanvas) then
            local clickPOs = Vector2.New(Input.mousePosition.x, Input.mousePosition.y)
            local p = EasyTouch.GetGameObjectAt(clickPOs, false)
            if not isNull(p) then
                local name = p.name
                if string.find(name, "BattleSelectionBtnPoint1") then
                    self:ExecuteButtonAction(Constants.SystemToggleIds.Id4)
                elseif string.find(name, "BattleSelectionBtnPoint2") then
                    self:ExecuteButtonAction(Constants.SystemToggleIds.Id5)
                elseif string.find(name, "BattleSelectionBtnPoint4") then
                    ---日常本的几个点的逻辑
                    self:ExecuteButtonAction(Constants.SystemToggleIds.Id6)
                end
            end
        end
    end)
end

function ActionDialog:ExecuteButtonAction(id, time)
    if id == self.selectId then
        return
    end
    self.selectId = id
    if not isNull(self.actionMap) then
        --Constants.SystemToggleIds.Id4 or checkNumber(id) == Constants.SystemToggleIds.Id5 or checkNumber(id) == Constants.SystemToggleIds.Id6
        self.actionMap:OnClickQuestEntry(id, time)
    end
end

function ActionDialog:DailyQuestButtonAction(copyType, id, go)
    self.selectId = id
    if not isNull(self.selectGo) then
        CfUtils.PlayAnimator(self.selectGo.transform:Find("Anim"), "Idle")
    end
    self.selectGo = go
    if not isNull(self.selectGo) then
        if checkNumber(KCookie.Get("IsHomeEntry")) == 1 then
            CfUtils.PlayAnimator(self.selectGo.transform:Find("Anim"), "SelectIdle")
        else
            CfUtils.PlayAnimator(self.selectGo.transform:Find("Anim"), "Select")
        end     
    end
    ----日常本
    xRecord.record('3-002')
    self.FightMap.enabled = true
    self.isEnabled = true
    ---@type DailyQuestDialog
    local env = CfUtils.GetLuaScr(self.FightMap.gameObject, DailyQuestDialogPath)
    env:FreshUI(copyType, id)
end

function ActionDialog:OnShow()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        --单独播一次open
        if not isNull(self.sceneRoot) then
            ---执行文本相关的定位
            local parameters = self.controller.Argument.parameters
            local env = CfUtils.GetLuaScr(self.sceneRoot, LuaPath)
            if parameters and checkNumber(parameters.type) > 0 then
                ---跳转过来的
                --Id4 = 4,          --金币副本
                --Id5 = 5,          --经验副本
                --Id6 = 6,          --升星材料副本

                local id = KCookie.Get("ActionDailyQuestId")
                if checkNumber(id) > 0 then
                    KCookie.Set("ActionDailyQuestId", 0)
                    parameters.type = checkNumber(id)
                elseif checkNumber(KCookie.Get("ActionLastMapId")) > 0 then   --这个有值直接return  不走后面的动画
                    KCookie.Set("ActionLastMapId", 0)
                    UIRaycastBlocker:RemoveCondition("ActionDialogBegin")
                    return
                end

                self._dailyAniCo = cs_coroutine.start(function()
                    while not self._isCanShowDailyAni do
                        coroutine.yield(Yielders.EndOfFrame)
                    end

                    self.isEnabled = true
                    env:OnClickDailyEntryQuestEntry(checkInt(parameters.type), 0.4)
                    UIRaycastBlocker:RemoveCondition("ActionDialogBegin")
                end)
            else
                local id = checkNumber(KCookie.Get("ActionDailyQuestId"))
                KCookie.Set("ActionDailyQuestId", 0)

                if id > 0 then
                    self._dailyAniCo = cs_coroutine.start(function()
                        while not self._isCanShowDailyAni do
                            coroutine.yield(Yielders.EndOfFrame)
                        end
    
                        env:OnClickDailyEntryQuestEntry(id, 0.4)
                        UIRaycastBlocker:RemoveCondition("ActionDialogBegin")
                    end)
                else
                    ---@type ActionEntryMap
                    env:PlayCamOpenAni()
                    UIRaycastBlocker:RemoveCondition("ActionDialogBegin")
                end
            end
        end

    end))
    return coWait
end

function ActionDialog:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        local CriWareUtils = import('Game.Entry.CriWareUtilsFix')
        CriWareUtils.PlayMusicById("bgm_action")
        
        ---@type SceneInstance
        local sceneInstance = sceneManagement:GetSceneInstance(Constants.IdSceneSetting29)
        if sceneInstance then
            sceneManagement:SetActive(Constants.IdSceneSetting29, true)
            ---获取一个节点
            self.sceneRoot = sceneInstance:GetCacheObjectByName(SceneNodeName)
            if not isNull(self.sceneRoot) then
                ---执行文本相关的定位
                ---@type ActionEntryMap
                local env = CfUtils.GetLuaScr(self.sceneRoot, LuaPath)
                env:RuntimeAnimator()
                self.actionMap = env
            end
        end
        local isFinish = false
        local t
        GameUtils.Request(Interfaces.PlayerActionHome, {}, function(request, response)
            if checkNumber(response.errCode) ~= 0 then
            end

            local jsonData = response.data
            local actionInfo = jsonData.actionInfo
            t = self:InitData(actionInfo)
            isFinish = true
        end)

        GameUtils.Request(Interfaces.ActivityHome, {}, function(request, response)
            if checkNumber(response.errCode) ~= 0 then
            end

            local jsonData = response.data
            
            --local isFind = false
            local data
            for k, v in pairs(jsonData.activities) do
                local activityType = checkNumber(v.type)
                --优先级顺序
                if activityType == ActivityConstants.ActivityType.PTQuest or activityType == ActivityConstants.ActivityType.PTMedium
                 or activityType == ActivityConstants.ActivityType.NightCat or activityType == ActivityConstants.ActivityType.HalloweenQuest
                 or activityType == ActivityConstants.ActivityType.Compete or activityType == ActivityConstants.ActivityType.SnowFestival
                 or activityType == ActivityConstants.ActivityType.MapDecryption
                then
                    if isNull(data) then
                        data = v
                    else
                        if checkNumber(v.id) > checkNumber(data.id) then
                            data = v
                        end
                    end
                end
            end
            local env = CfUtils.GetLuaScr(self.sceneRoot, LuaPath)
            env:FillActivityInfo(data)
        end)

        self._co = cs_coroutine.start(function()
            --coroutine.yield(WaitForSeconds(0.717))
            while not isFinish do
                coroutine.yield(Yielders.EndOfFrame)
            end
            if not isNull(self.sceneRoot) then
                ---执行文本相关的定位
                ---@type ActionEntryMap
                local env = CfUtils.GetLuaScr(self.sceneRoot, LuaPath)
                env:FreshUI(t, { self.UIFX_BattleSelectionEntryCenterToB, self.UIFX_BattleSelectionEntryCenterToC, self.UIFX_BattleSelectionEntryCenterToL })
            end
            self._isCanShowDailyAni = true
        end)

        --[[
        while not isFinish do
            coroutine.yield(Yielders.EndOfFrame)
        end
        ]]
    end))
    return coWait
end

function ActionDialog:InitData(actionInfo)
    if not actionInfo then
        return {}
    end
    local t = {}
    for k, v in pairs(actionInfo) do
        t[checkString(k)] = v
        if checkNumber(k) == Constants.SystemToggleIds.Id15 then
            --爬塔
            local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.TowerQuestComponent)
            comp:Initial(v)
        elseif checkNumber(k) == Constants.SystemToggleIds.Id14 then
            local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.WorldBossComponent)
            comp:InitialBossInfo(v)
        elseif checkNumber(k) == Constants.SystemToggleIds.Id22 then
            local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.TalentQuestComponent)
            comp:InitActiveInfo(v)
        elseif checkNumber(k) == Constants.SystemToggleIds.Id16 then
            -- ---@type PVPArenaComponent
            -- local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PVPArenaComponent)
            -- comp:InitEntry(v)
        end
    end
    return t
end

function ActionDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        if not isNull(self.sceneRoot) then
            ---执行文本相关的定位
            ---@type ActionEntryMap
            local env = CfUtils.GetLuaScr(self.sceneRoot, LuaPath)
            env:RemoveTimeDown()
        end
        KCookie.Set("IsHomeEntry", 0)

        if self.actionHandler then
            Events.RemoveListener(Constants.EventNames.DAILY_QUEST_BUTTON_CLICK_ACTION, self.actionHandler)
        end
        local navigatorBar = GetLuaBehaviour(UINavigationBarRoot.Instance.gameObject, "Game.Main.UINavigatorBar")
        if not isNull(navigatorBar) then
            if not KTool.IsNull(navigatorBar.Env) then
                navigatorBar.Env:SetCustomBackHandlerAction(nil)
            end
        end
        if not isNull(self.sceneRoot) then
            ---执行文本相关的定位
            ---@type ActionEntryMap
            local env = CfUtils.GetLuaScr(self.sceneRoot, LuaPath)
            ----删除copy过来的动画控制器
            env:DeleteAnimator()
        end
        self.actionHandler = nil
        local sceneInstance = sceneManagement:GetSceneInstance(Constants.IdSceneSetting29)
        if sceneInstance then
            sceneManagement:SetActive(Constants.IdSceneSetting29, false, true)
        end
        if self._showCo then 
            cs_coroutine.stop(self._showCo)
            self._showCo = nil
        end
        if self._dailyAniCo then 
            cs_coroutine.stop(self._dailyAniCo)
            self._dailyAniCo = nil
        end

        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return ActionDialog